namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new() { Id = 1, Title = "Fluffy Pancakes", Category = RecipeCategory.Breakfast, Ingredients = "2 cups flour\n2 eggs\n1 cup milk\n2 tbsp sugar\n1 tsp baking powder", Steps = "1. Mix dry ingredients\n2. Whisk eggs and milk\n3. Combine wet and dry\n4. Cook on griddle until golden", AverageRating = 4.5, RatingCount = 12 },
        new() { Id = 2, Title = "Caesar Salad", Category = RecipeCategory.Lunch, Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan\nCaesar dressing", Steps = "1. Chop lettuce\n2. Toss with dressing\n3. Top with croutons and parmesan", AverageRating = 4.0, RatingCount = 8 },
        new() { Id = 3, Title = "Grilled Salmon", Category = RecipeCategory.Dinner, Ingredients = "4 salmon fillets\n2 tbsp olive oil\nLemon juice\nGarlic\nDill", Steps = "1. Marinate salmon in oil, lemon, garlic\n2. Preheat grill to medium-high\n3. Grill 4-5 min per side\n4. Garnish with dill", AverageRating = 4.8, RatingCount = 20 },
        new() { Id = 4, Title = "Chocolate Brownies", Category = RecipeCategory.Desserts, Ingredients = "1 cup butter\n2 cups sugar\n4 eggs\n1 cup cocoa powder\n1 cup flour", Steps = "1. Melt butter, mix with sugar\n2. Beat in eggs\n3. Fold in cocoa and flour\n4. Bake at 350°F for 25 min", AverageRating = 4.9, RatingCount = 35 },
        new() { Id = 5, Title = "Trail Mix Energy Bites", Category = RecipeCategory.Snacks, Ingredients = "1 cup oats\n1/2 cup peanut butter\n1/3 cup honey\n1/2 cup chocolate chips\n1/2 cup flaxseed", Steps = "1. Mix all ingredients\n2. Chill 30 minutes\n3. Roll into balls\n4. Store in fridge", AverageRating = 4.2, RatingCount = 15 },
        new() { Id = 6, Title = "Avocado Toast", Category = RecipeCategory.Breakfast, Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\nLemon juice", Steps = "1. Toast bread\n2. Mash avocado with lemon juice\n3. Spread on toast\n4. Season with salt, pepper, and red pepper flakes", AverageRating = 4.3, RatingCount = 10 },
        new() { Id = 7, Title = "Chicken Stir Fry", Category = RecipeCategory.Dinner, Ingredients = "2 chicken breasts\n2 cups mixed vegetables\n3 tbsp soy sauce\n1 tbsp sesame oil\nRice", Steps = "1. Slice chicken into strips\n2. Stir-fry chicken in sesame oil\n3. Add vegetables\n4. Add soy sauce\n5. Serve over rice", AverageRating = 4.4, RatingCount = 18 },
    ];

    private int _nextId = 8;

    public List<Recipe> GetAll() => _recipes;

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void Add(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }
}
