@page "/recipes/{category?}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Recipes - @(Category ?? "All") | RecipeShare</PageTitle>

<h1>@(Category is not null ? $"{Category} Recipes" : "All Recipes")</h1>

@if (Category is null)
{
    <div class="mb-3">
        @foreach (var cat in RecipeCategory.All)
        {
            <a href="recipes/@cat.ToLower()" class="btn btn-outline-secondary me-2 mb-2">@cat</a>
        }
    </div>
}
else
{
    <a href="recipes" class="btn btn-outline-secondary mb-3">← All Categories</a>
}

<div class="row">
    @foreach (var recipe in Recipes)
    {
        <div class="col-md-6 mb-3">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <p class="card-text text-muted">@recipe.Category</p>
                    <p class="card-text">
                        <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                        <small class="text-muted">(@recipe.AverageRating / 5, @recipe.RatingCount ratings)</small>
                    </p>
                    <a href="recipe/@recipe.Id" class="btn btn-sm btn-primary">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@if (!Recipes.Any())
{
    <p class="text-muted">No recipes found in this category yet.</p>
}

@code {
    [Parameter] public string? Category { get; set; }

    private List<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = Category is not null
            ? RecipeService.GetByCategory(Category)
            : RecipeService.GetAll();
    }
}

