﻿@page "/"
@using RecipeShare.Models

<PageTitle>RecipeShare - Home</PageTitle>

<h1>🍳 Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes with our community.</p>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in RecipeCategory.All)
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h3 class="card-title">@GetEmoji(category) @category</h3>
                    <p class="card-text">Explore our @category.ToLower() recipes</p>
                    <a href="recipes/@category.ToLower()" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string GetEmoji(string category) => category switch
    {
        "Breakfast" => "🥞",
        "Lunch" => "🥗",
        "Dinner" => "🍽️",
        "Desserts" => "🍰",
        "Snacks" => "🍿",
        _ => "🍴"
    };
}

