@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") | RecipeShare</PageTitle>

@if (Recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="recipes" class="btn btn-primary">Back to Recipes</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">Recipes</a></li>
            <li class="breadcrumb-item"><a href="recipes/@Recipe.Category.ToLower()">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <p class="text-muted">Category: @Recipe.Category</p>

    <StarRating RecipeId="Recipe.Id" CurrentRating="Recipe.AverageRating" RatingCount="Recipe.RatingCount" />

    <h2 class="mt-4">Ingredients</h2>
    <ul>
        @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h2>Steps</h2>
    <ol>
        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && text[0] is >= '0' and <= '9' && text.Contains('.'))
            {
                text = text[(text.IndexOf('.') + 1)..].TrimStart();
            }
            <li>@text</li>
        }
    </ol>

    <a href="recipes/@Recipe.Category.ToLower()" class="btn btn-outline-secondary mt-3">← Back to @Recipe.Category</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="my-3 p-3 border rounded">
    <h5>Rate this recipe</h5>
    <div class="star-rating" style="font-size: 1.5rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => Rate(star)"
                  @onmouseover="() => _hover = star"
                  @onmouseout="() => _hover = 0"
                  class="@(star <= DisplayStars ? "text-warning" : "text-muted")">
                ★
            </span>
        }
    </div>
    <p class="mt-2 mb-0">
        @if (_submitted)
        {
            <span class="text-success">Thanks for rating! You gave @_userRating star(s).</span>
        }
        else
        {
            <span class="text-muted">@CurrentRating / 5 (@RatingCount ratings) — click a star to rate</span>
        }
    </p>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hover;
    private int _userRating;
    private bool _submitted;

    private int DisplayStars => _hover > 0 ? _hover : (_submitted ? _userRating : (int)Math.Round(CurrentRating));

    private void Rate(int stars)
    {
        _userRating = stars;
        _submitted = true;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

